SELECT ?zone ?point ?ts WHERE {
  ?zone brick:hasSubProperty? .
  ?point brick:isTypeOf* brick:AirTemperature OR ?point a brick:AirTemperature .
  ?point ref:hasTimeseriesId ?ts .
  FILTER(str(?point) && "ZN_4" || str(?zone) && "ZN_4")
}

SELECT ?zone ?point ?ts WHERE {
  ?point a brick:AirTemperature .
  ?point ref:hasTimeseriesId ?ts .
  ?point brick:hasPropertyOf ?zone .
  FILTER(str(?zone) LIKE "%ZN_4%")
}

SELECT ?zone ?point ?ts WHERE {
  ?point a brick:AirTemperature .
  ?point ref:hasTimeseriesId ?ts .
  ?point brick:hasPropertyOf ?zone .
}

